input.command:
echo "=== binaries from the 41 migrated formulae: where do they resolve? ==="
BAD=0
for t in git gh git-lfs go jq rg ast-grep csview ctags dos2unix eksctl gdb helm kubectl mc mitmproxy mysql newman node parquet-cli podman pdftotext psql pylint isort qemu-img telnet tmux tree trivy wget guile mvn codex unbound truncate uv conda; do
  loc=$(command -v $t 2>/dev/null) || { echo "  (absent)    $t"; continue; }
  case "$loc" in
    /opt/homebrew/*) printf "  ARM  OK     %-14s %s\n" "$t" "$loc";;
    /usr/local/*)    printf "  >>> X86     %-14s %s\n" "$t" "$loc"; BAD=$((BAD+1));;
    *)               printf "  system      %-14s %s\n" "$t" "$loc";;
  esac
done
echo
echo "STILL RESOLVING TO /usr/local: $BAD"
